using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;using System.Text.Json.Nodes;
namespace RaceDay.Mvc.Controllers;
public class ParticipantController(RaceDayApiClient api):Controller {
 bool Guard()=>HttpContext.Session.GetString("Role")=="Participant"&&!string.IsNullOrEmpty(HttpContext.Session.GetString("Token")); IActionResult Deny()=>RedirectToAction("Login","Account");
 public async Task<IActionResult> Index(string? location,DateTime? date){if(!Guard())return Deny();try{var query="api/events"+(string.IsNullOrWhiteSpace(location)&&!date.HasValue?"":"?"+string.Join("&",new[]{string.IsNullOrWhiteSpace(location)?null:"location="+Uri.EscapeDataString(location),date.HasValue?"date="+date.Value.ToString("yyyy-MM-dd"):null}.Where(x=>x!=null)));ViewBag.Events=await api.Get(query);ViewBag.Location=location;ViewBag.Date=date;}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 public async Task<IActionResult> Details(int id){if(!Guard())return Deny();try{ViewBag.Event=await api.Get($"api/events/{id}");ViewBag.Categories=await api.Get($"api/events/{id}/categories");}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Enrol(int categoryId){if(!Guard())return Deny();try{await api.Send($"api/categories/{categoryId}/enrol",HttpMethod.Post);TempData["Success"]="You have successfully entered this event.";}catch(Exception e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(MyEvents));}
 public async Task<IActionResult> MyEvents(){if(!Guard())return Deny();try{ViewBag.Enrolments=await api.Get("api/enrolments/me");}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 public async Task<IActionResult> MyResults(){if(!Guard())return Deny();try{ViewBag.Results=await api.Get("api/results/me");}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 public async Task<IActionResult> Profile(){if(!Guard())return Deny();try{ViewBag.Profile=await api.Get("api/users/me");}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> UpdateProfile(string fullName,IFormFile? profilePicture){if(!Guard())return Deny();try{string? url=null;if(profilePicture!=null){var upload=await api.Upload("api/uploads/profile-picture",profilePicture);url=upload?["url"]?.ToString();}var old=await api.Get("api/users/me");await api.Send("api/users/me",HttpMethod.Put,new{fullName,profilePictureURL=url??old?["profilePictureURL"]?.ToString()});TempData["Success"]="Profile updated.";}catch(Exception e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Profile));}
}
